<script setup lang="ts">
const props=defineProps<{warehouseId:number;filters?:Record<string,any>}>()
const {t}=useI18n(),staff=useStaffStore(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),loading=ref(false),error=ref(''),page=ref(1),status=ref(''),table=ref(false)
const colours:Record<string,string>={normal:'#7855FE',warning:'#E99B1A',blocked:'#DB2C2B',unknown:'#CDD1DA'}
let generation=0
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;const result=await httpRequest<any>('/api/warehouse/inventory/expiry',{headers:warehouseHeaders(props.warehouseId),params:{...props.filters,page:page.value,per_page:20,status:status.value||undefined},onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
const groups=computed(()=>{const map=new Map<number,any>();for(const row of data.value?.items||[]){if(!map.has(row.goods_id))map.set(row.goods_id,{id:row.goods_id,name:row.goods_name,code:row.goods_code,ship:row.ship_days,warning:row.warning_days,rows:[]});map.get(row.goods_id).rows.push(row)}return [...map.values()].map(group=>({...group,max:Math.max(1,group.ship,group.warning,...group.rows.map((row:any)=>row.remaining_days||0))}))})
const columns=computed(()=>[{key:'goods_name',label:t('nav.goods'),wrap:true},{key:'lot_no',label:t('goods-label.lot'),value:(row:any)=>row.lot_no||t('lot-rules.unassigned')},{key:'expiry_date',label:t('goods-label.expiry')},{key:'quantity',label:t('common.fields.quantity'),type:'qty' as const,keepZero:true},{key:'status',label:t('common.fields.status'),format:(value:string)=>t('expiry.'+value)}])
watch(()=>props.warehouseId,()=>{if(page.value!==1)page.value=1;else load()});watch(page,load);onMounted(load);onBeforeUnmount(()=>generation++)
const filter=(value:string)=>{status.value=status.value===value?'':value;if(page.value!==1)page.value=1;else load()}
</script>
<template><WCard flush><section class="expiry"><header><h2>{{t('expiry.title')}}<WHelp :text="t('expiry.help')"/></h2><WButton size="sm" variant="text" @click="table=!table">{{t(table?'expiry.chart':'expiry.table')}}</WButton></header><p>{{t('inventory-analysis.asof')}} {{data?.as_of||'—'}}</p><div class="legend"><button v-for="(colour,key) in colours" :key="key" :aria-pressed="status===key" :class="{active:status===key}" @click="filter(key)"><i :style="{background:colour}"/>{{t('expiry.'+key)}} <b>{{data?.summary?.[key]??'—'}}</b></button></div><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WEmptyState v-if="loading" :title="t('common.status.loading')"/><WTable v-else-if="table" :rows="data?.items||[]" :columns="columns"/><template v-else><div v-for="group in groups" :key="group.id" class="group"><header><NuxtLink v-if="staff.hasPermission('goods_read')" :to="{path:'/goods/detail/'+group.id,query:{tab:'lots'}}">{{group.code}} · {{group.name}}</NuxtLink><strong v-else>{{group.code}} · {{group.name}}</strong><small>{{t('lot-rules.ship_days')}} {{group.ship}} · {{t('lot-rules.warning_days')}} {{group.warning}}</small></header><div v-for="row in group.rows" :key="row.lot_id??0" class="line"><div><span>{{row.lot_no||t('lot-rules.unassigned')}}</span><small>{{row.expiry_date||t('location-map.unknown')}}</small></div><div class="track" :aria-label="t('expiry.'+row.status)"><i v-if="row.remaining_days!==null" :style="{width:Math.max(0,row.remaining_days)/group.max*100+'%',background:colours[row.status]}"/><span class="limit shipping" :style="{left:group.ship/group.max*100+'%'}" :title="t('lot-rules.ship_days')"/><span class="limit warning" :style="{left:group.warning/group.max*100+'%'}" :title="t('lot-rules.warning_days')"/></div><div class="quantity"><b>{{row.quantity}}</b><small :style="{color:colours[row.status]}">{{t('expiry.'+row.status)}}</small></div></div></div><WEmptyState v-if="!groups.length&&!error" :title="t('expiry.empty')"/></template><footer><WPagination v-model:page="page" :page-size="20" :total="data?.total||0" show-total/></footer></section></WCard></template>
<style scoped>.expiry{padding:20px}.expiry>header,.group>header{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px}.expiry h2{font-size:16px;line-height:24px;margin:0;display:flex;align-items:center;gap:8px}.expiry p,small{font-size:12px;line-height:18px;color:var(--w-text-3)}.legend{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.legend button{display:flex;align-items:center;gap:6px;padding:6px 8px;font:inherit;font-size:12px;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--w-text-2);cursor:pointer}.legend button.active{border-color:var(--w-pri);background:var(--w-sel-soft)}.legend i{width:8px;height:8px;border-radius:2px}.group{margin-top:20px}.group>header{font-size:13px;margin-bottom:8px}.group a{color:var(--w-link)}.line{display:grid;grid-template-columns:220px minmax(0,1fr) 100px;gap:12px;align-items:center;padding:10px 0;border-top:1px solid var(--w-line);font-size:13px}.line small{display:block}.track{position:relative;height:20px;background:var(--w-bg)}.track>i{display:block;height:100%;border-radius:0 3px 3px 0}.limit{position:absolute;top:-3px;bottom:-3px;border-left:1px dashed}.shipping{border-color:#DB2C2B}.warning{border-color:#E99B1A}.quantity{text-align:right}footer{margin-top:16px}@media(max-width:650px){.expiry{padding:16px}.line{grid-template-columns:110px minmax(0,1fr) 65px;gap:8px}.line>div:first-child{overflow-wrap:anywhere}.group>header{align-items:start;flex-direction:column}}</style>
